export class VeilPayError extends Error { constructor(message, code) { super(`[VeilPay SDK] ${message}`); this.code = code; this.name = "VeilPayError"; } }
export class VeilPayInitError extends VeilPayError { constructor(message) { super(message, "INIT_FAILURE"); this.name = "VeilPayInitError"; } }
export class VeilPayEncryptionError extends VeilPayError { constructor(message) { super(message, "ENCRYPTION_FAILURE"); this.name = "VeilPayEncryptionError"; } }
export class VeilPayContractError extends VeilPayError { constructor(message, txHash) { super(message, "CONTRACT_FAILURE"); this.txHash = txHash; this.name = "VeilPayContractError"; } }
export class VeilPayValidationError extends VeilPayError { constructor(message) { super(message, "VALIDATION_FAILURE"); this.name = "VeilPayValidationError"; } }